CustomField.formula:
IF(
    /* Check if the current month and year match the picklist values */
    AND(
        VALUE(TEXT(Month__c)) = MONTH(TODAY()), 
        VALUE(TEXT(Year__c)) = YEAR(TODAY())
    ), 
    "This Month", /* If they match, display "This Month" */

    /* Check if the picklist month and year correspond to last month */
    IF(
        AND(
            VALUE(TEXT(Month__c)) = 
                IF(MONTH(TODAY()) = 1, 12, MONTH(TODAY()) - 1), /* Handle December -> January transition */
            VALUE(TEXT(Year__c)) = 
                IF(MONTH(TODAY()) = 1, YEAR(TODAY()) - 1, YEAR(TODAY()))
        ), 
        "Last Month", /* If it matches, display "Last Month" */

        /* Check if the picklist month and year correspond to next month */
        IF(
            AND(
                VALUE(TEXT(Month__c)) = 
                    IF(MONTH(TODAY()) = 12, 1, MONTH(TODAY()) + 1), /* Handle January -> December transition */
                VALUE(TEXT(Year__c)) = 
                    IF(MONTH(TODAY()) = 12, YEAR(TODAY()) + 1, YEAR(TODAY()))
            ), 
            "Next Month", /* If it matches, display "Next Month" */

            "" /* If none of the above conditions are true, leave it blank */
        )
    )
)
